/**
 * @summary List messages in a conversation
 */
export const getListMessagesUrl = (id: number, convId: number) => {
  return `/api/chatbots/${id}/conversations/${convId}/messages`;
};

export const listMessages = async (
  id: number,
  convId: number,
  options?: RequestInit,
): Promise<Message[]> => {
  return customFetch<Message[]>(getListMessagesUrl(id, convId), {
    ...options,
    method: "GET",
  });
};

export const getListMessagesQueryKey = (id: number, convId: number) => {
  return [`/api/chatbots/${id}/conversations/${convId}/messages`] as const;
};

export const getListMessagesQueryOptions = <
  TData = Awaited<ReturnType<typeof listMessages>>,
  TError = ErrorType<unknown>,
>(
  id: number,
  convId: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listMessages>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getListMessagesQueryKey(id, convId);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listMessages>>> = ({
    signal,
  }) => listMessages(id, convId, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!(id && convId),
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof listMessages>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

