/**
 * @summary Send a message via the embeddable widget (public endpoint)
 */
export const getWidgetChatUrl = (chatbotUid: string) => {
  return `/api/widget/${chatbotUid}/chat`;
};

export const widgetChat = async (
  chatbotUid: string,
  widgetMessageInput: WidgetMessageInput,
  options?: RequestInit,
): Promise<WidgetMessageResponse> => {
  return customFetch<WidgetMessageResponse>(getWidgetChatUrl(chatbotUid), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(widgetMessageInput),
  });
};

export const getWidgetChatMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof widgetChat>>,
    TError,
    { chatbotUid: string; data: BodyType<WidgetMessageInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof widgetChat>>,
  TError,
  { chatbotUid: string; data: BodyType<WidgetMessageInput> },
  TContext
> => {
  const mutationKey = ["widgetChat"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof widgetChat>>,
    { chatbotUid: string; data: BodyType<WidgetMessageInput> }
  > = (props) => {
    const { chatbotUid, data } = props ?? {};

    return widgetChat(chatbotUid, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type WidgetChatMutationResult = NonNullable<
  Awaited<ReturnType<typeof widgetChat>>
>;
export type WidgetChatMutationBody = BodyType<WidgetMessageInput>;
export type WidgetChatMutationError = ErrorType<unknown>;

/**
 * @summary Send a message via the embeddable widget (public endpoint)
 */
export const useWidgetChat = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof widgetChat>>,
    TError,
    { chatbotUid: string; data: BodyType<WidgetMessageInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof widgetChat>>,
  TError,
  { chatbotUid: string; data: BodyType<WidgetMessageInput> },
  TContext
> => {
  return useMutation(getWidgetChatMutationOptions(options));
};
